#include "terminal.hpp"
#include <iostream>

using namespace hub;
namespace {
bool settled(PasswordPipe&pipe,DWORD timeout){auto deadline=GetTickCount64()+timeout;while(GetTickCount64()<deadline){if(pipe.delivered()||!pipe.error().empty())return true;Sleep(1);}return pipe.delivered()||!pipe.error().empty();}
Handle connect(PasswordPipe&pipe){pipe.bind(GetCurrentProcess(),GetCurrentProcessId());Handle peer(CreateFileW(pipe.name().c_str(),GENERIC_READ,0,nullptr,OPEN_EXISTING,FILE_ATTRIBUTE_NORMAL,nullptr));check(static_cast<bool>(peer),"Open owned fixture pipe reader");return peer;}
void buffered(HANDLE peer){auto deadline=GetTickCount64()+2000;while(GetTickCount64()<deadline){DWORD available=0;check(PeekNamedPipe(peer,nullptr,0,nullptr,&available,nullptr)!=FALSE,"Observe unread fixture bytes");if(available)return;Sleep(1);}throw std::runtime_error("No fixture data became available");}
Json no_reader(){PasswordPipe pipe(std::string(24,'x'));pipe.cancel();auto done=settled(pipe,1000);return Json{{"case","cancel_without_reader"},{"passed",done&&!pipe.delivered()&&!pipe.error().empty()}};}
Json unread_reader(){auto pipe=std::make_unique<PasswordPipe>(std::string(24,'x'));auto peer=connect(*pipe);buffered(peer.get());auto before=pipe->delivered();auto start=GetTickCount64();pipe->cancel();auto done=settled(*pipe,1000);auto elapsed=GetTickCount64()-start;auto delivered=pipe->delivered();auto error=!pipe->error().empty();peer.reset();pipe.reset();return Json{{"case","cancel_with_connected_unread_reader"},{"passed",done&&!delivered&&error},{"reportedDeliveredBeforeCancel",before},{"settledBeforePeerClosed",done},{"reportedDeliveredBeforePeerClosed",delivered},{"errorBeforePeerClosed",error},{"cancelWaitMs",elapsed}};}
Json normal_reader(){PasswordPipe pipe(std::string(24,'x'));auto peer=connect(pipe);char data[128]{};DWORD n=0;check(ReadFile(peer.get(),data,sizeof(data),&n,nullptr)!=FALSE,"Read synthetic fixture bytes");auto expected=n==25&&data[24]=='\n';SecureZeroMemory(data,sizeof(data));auto done=settled(pipe,1000);return Json{{"case","normal_reader"},{"passed",expected&&done&&pipe.delivered()&&pipe.error().empty()}};}
}
int wmain(int argc,wchar_t**argv){try{if(argc==2&&std::wstring_view(argv[1])==L"--timeout"){auto pipe=std::make_unique<PasswordPipe>(std::string(24,'x'));auto peer=connect(*pipe);buffered(peer.get());auto start=GetTickCount64();auto done=settled(*pipe,65000);auto elapsed=GetTickCount64()-start;auto passed=done&&!pipe->delivered()&&!pipe->error().empty()&&elapsed>=59000&&elapsed<=63000;peer.reset();pipe.reset();Json report{{"status",passed?"passed":"failed"},{"case","connected_unread_reader_timeout"},{"settledBeforePeerClosed",done},{"elapsedMs",elapsed},{"scope","Real default delivery timeout with same-process unread synthetic pipe consumer"}};write_text(root()/L"evidence/pipe-timeout-results.json",report.dump(2));std::cout<<report.dump(2)<<"\n";return passed?0:1;}Json cases=Json::array();cases.push_back(no_reader());cases.push_back(unread_reader());cases.push_back(normal_reader());bool passed=true;for(auto&result:cases)passed=passed&&result.at("passed").get<bool>();Json report{{"status",passed?"passed":"failed"},{"scope","Same-user PID-bound synthetic pipe reader, cancellation and normal read; no real credentials or GUI"},{"cases",cases}};write_text(root()/L"evidence/pipe-results.json",report.dump(2));std::cout<<report.dump(2)<<"\n";return passed?0:1;}catch(const std::exception&e){write_text(root()/L"evidence/pipe-error.txt",e.what());std::cerr<<e.what()<<"\n";return 1;}}
